import gurobipy as gp
from gurobipy import GRB

suppliers = ['S1', 'S2']
customers = ['C1', 'C2']
demand = {'C1': 7564, 'C2': 5246}
fixed_cost = {'S1': 105.18150830480553, 'S2': 112.1842388512642}
cost = {'S1': {'C1': 937.3406504757702, 'C2': 86.93019411027852}, 'S2': {'C1': 49.3801614788785, 'C2': 1726.0621013627836}}
M = sum(demand.values())

m = gp.Model('Original_RAG_FLP')
x = m.addVars(suppliers, customers, lb=0, vtype=GRB.CONTINUOUS, name='x')
y = m.addVars(suppliers, vtype=GRB.BINARY, name='y')
m.setObjective(gp.quicksum(cost[i][j] * x[i, j] for i in suppliers for j in customers)
               + gp.quicksum(fixed_cost[i] * y[i] for i in suppliers), GRB.MINIMIZE)
m.addConstrs((gp.quicksum(x[i, j] for i in suppliers) == demand[j]
              for j in customers), name='demand')
m.addConstrs((gp.quicksum(x[i, j] for j in customers) <= M * y[i]
              for i in suppliers), name='activation')

m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for variable in m.getVars():
        print(f'{variable.VarName}: {variable.X}')
else:
    print(f'Solver status: {m.Status}')

import gurobipy as gp
from gurobipy import GRB

items = ['Nike x Olivia Kim Air Footscape', "Nike x Olivia Kim Air Force 1 '07", 'Nike x Olivia Kim Air Max 98', 'Nike x Olivia Kim Air Mowabb']
revenue = {'Nike x Olivia Kim Air Footscape': 9097, "Nike x Olivia Kim Air Force 1 '07": 9995, 'Nike x Olivia Kim Air Max 98': 11197, 'Nike x Olivia Kim Air Mowabb': 11197}
inventory = {'Nike x Olivia Kim Air Footscape': 240, "Nike x Olivia Kim Air Force 1 '07": 281, 'Nike x Olivia Kim Air Max 98': 322, 'Nike x Olivia Kim Air Mowabb': 97}
demand = {'Nike x Olivia Kim Air Footscape': 26, "Nike x Olivia Kim Air Force 1 '07": 53, 'Nike x Olivia Kim Air Max 98': 50, 'Nike x Olivia Kim Air Mowabb': 17}

if sum(demand[i] for i in items) < 100:
    raise ValueError("Trading requires total demand of at least 100 across the four selected styles.")

m = gp.Model('Original_RAG_NRM')
x = m.addVars(items, lb=1, vtype=GRB.INTEGER, name='x')
m.setObjective(gp.quicksum(revenue[i] * x[i] for i in items), GRB.MAXIMIZE)
m.addConstrs((x[i] <= inventory[i] for i in items), name='inventory')
m.addConstrs((x[i] <= demand[i] for i in items), name='demand')

# Synthetic scenario parameter; original source data are unchanged.
m.addConstr(gp.quicksum(x[i] for i in items) <= 100, name='dispatch_capacity')

m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for variable in m.getVars():
        print(f'{variable.VarName}: {variable.X}')
else:
    print(f'Solver status: {m.Status}')

import gurobipy as gp
import pandas as pd
import numpy as np
import sys
import re

def find_col(df, pattern):
    for col in df.columns:
        if re.search(pattern, col, re.IGNORECASE):
            return col
    raise KeyError(f"Could not find a column matching pattern '{{pattern}}'")
try:
    products = [1, 2, 3]
    profit = {1: 39.62, 2: 35.98, 3: 37.96}
    fixed_cost = {1: 178539, 2: 157708, 3: 85192}
    demand = {1: 5732, 2: 5607, 3: 4653}
    quota = {1: 12892, 2: 7238, 3: 11902}
    min_batch = {1: 18, 2: 25, 3: 23}
    m = gp.Model('ProductionOptimization')
    x = m.addVars(products, vtype=gp.GRB.INTEGER, name='x')
    y = m.addVars(products, vtype=gp.GRB.BINARY, name='y')
    objective = gp.quicksum((profit[i] * x[i] - fixed_cost[i] * y[i] for i in products))
    m.setObjective(objective, gp.GRB.MAXIMIZE)
    m.addConstrs((x[i] <= demand[i] for i in products), name='demand')
    m.addConstrs((x[i] <= quota[i] for i in products), name='quota')
    m.addConstrs((x[i] >= min_batch[i] * y[i] for i in products), name='min_batch')
    m.addConstrs((x[i] <= demand[i] * y[i] for i in products), name='linking')
    m.addConstr(gp.quicksum((x[i] / {1: 586, 2: 329, 3: 541}[i] for i in products)) <= 22, name='shared_production_days')
    m.optimize()
    if m.status == gp.GRB.OPTIMAL:
        print(f'Optimal total value/cost: {m.objVal:.2f}')
        print('--- Production Plan ---')
        for i in products:
            if y[i].X > 0.5:
                print(f'Product {i}:')
                print(f'  Status: ACTIVE (y{i} = {y[i].X:.0f})')
                print(f'  Production: {x[i].X:.0f} (100kg units)')
            else:
                print(f'Product {i}:')
                print(f'  Status: INACTIVE (y{i} = {y[i].X:.0f})')
                print(f'  Production: {x[i].X:.0f} (100kg units)')
    else:
        print(f'No optimal solution found. Status: {m.status}')
except KeyError as e:
    print(f'Data Error: A required column was not found. {e}', file=sys.stderr)
except pd.errors.EmptyDataError as e:
    print(f'Data Error: CSV file is empty or unreadable. {e}', file=sys.stderr)
except Exception as e:
    print(f'An unexpected error occurred: {e}', file=sys.stderr)

import gurobipy as gp
from gurobipy import GRB

items = ['Sony Alpha Refrigerator', 'Sony Bravia XR', 'Sony HT-A7000 Soundbar', 'Sony PlayStation 5', 'Sony PlayStation Soundbar']
shelves = ['1', '2', '3', '4', '5', '6']
profit = {'Sony Alpha Refrigerator': 1818, 'Sony Bravia XR': 1609, 'Sony HT-A7000 Soundbar': 509, 'Sony PlayStation 5': 1808, 'Sony PlayStation Soundbar': 528}
space = {'Sony Alpha Refrigerator': 400, 'Sony Bravia XR': 200, 'Sony HT-A7000 Soundbar': 40, 'Sony PlayStation 5': 60, 'Sony PlayStation Soundbar': 50}
sony_limit = {'1': 1200, '2': 1374, '3': 800, '4': 2042, '5': 1000, '6': 1800}

m = gp.Model('Original_RAG_RA')
x = m.addVars(items, shelves, lb=0, vtype=GRB.INTEGER, name='x')
m.setObjective(gp.quicksum(profit[i] * x[i, j] for i in items for j in shelves), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum(space[i] * x[i, j] for i in items) <= sony_limit[j]
              for j in shelves), name='sony_space')

m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for variable in m.getVars():
        print(f'{variable.VarName}: {variable.X}')
else:
    print(f'Solver status: {m.Status}')

import gurobipy as gp
from gurobipy import GRB

suppliers = ['S1', 'S2', 'S3']
customers = ['C1', 'C2', 'C3', 'C4']
demand = {'C1': 11, 'C2': 1148, 'C3': 54, 'C4': 833}
supply_capacity = {'S1': 4, 'S2': 575, 'S3': 1504}
cost = {'S1': {'C1': 0.63, 'C2': 49.71, 'C3': 33.75, 'C4': 1570.67}, 'S2': {'C1': 605.47, 'C2': 64.53, 'C3': 478.47, 'C4': 887.04}, 'S3': {'C1': 1139.04, 'C2': 4.78, 'C3': 1805.62, 'C4': 1302.89}}

m = gp.Model('Original_RAG_TP')
x = m.addVars(suppliers, customers, lb=0, vtype=GRB.CONTINUOUS, name='x')
m.setObjective(gp.quicksum(cost[i][j] * x[i, j] for i in suppliers for j in customers), GRB.MINIMIZE)
m.addConstrs((gp.quicksum(x[i, j] for i in suppliers) >= demand[j]
              for j in customers), name='demand')
m.addConstrs((gp.quicksum(x[i, j] for j in customers) <= supply_capacity[i]
              for i in suppliers), name='supply')

m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for variable in m.getVars():
        print(f'{variable.VarName}: {variable.X}')
else:
    print(f'Solver status: {m.Status}')
